QUIZ_DATABASE["N4"]["dochieu"] = {"label": "Đọc Hiểu", "unitLabel": "bài", "slots": 25, "tests": {"1": {"title": "Bài 26 — Đọc hiểu Minna no Nihongo", "passage": "わたしは 来月（らいげつ）から 東京（とうきょう）で 働（はたら）くんです。いま 住（す）む ところを 探（さが）して います。駅（えき）に 近（ちか）くて、静（しず）かな ところが いいんです。家賃（やちん）は ８万円（まんえん）ぐらいまでなら いいと 思（おも）っています。", "questions": [{"q": "Người viết sắp làm gì?", "options": ["Nghỉ việc ở Tokyo", "Đến Tokyo làm việc từ tháng sau", "Chuyển việc về quê", "Đi du lịch Tokyo"], "answer": 1, "explain": "「来月から東京で働くんです」 — mẫu ～んです giải thích tình hình (Bài 26)."}, {"q": "Người viết đang tìm gì?", "options": ["Việc làm mới", "Trường học", "Bạn cùng phòng", "Nơi ở / nhà thuê"], "answer": 3, "explain": "「住むところを探しています」 = đang tìm chỗ ở."}, {"q": "Người viết muốn nhà như thế nào?", "options": ["Có sân vườn", "Gần công ty và mới", "Rộng và rẻ", "Gần ga và yên tĩnh"], "answer": 3, "explain": "「駅に近くて、静かなところがいいんです」."}, {"q": "Tiền nhà tối đa người viết chấp nhận là bao nhiêu?", "options": ["Khoảng 12 vạn yên", "Khoảng 5 vạn yên", "Khoảng 10 vạn yên", "Khoảng 8 vạn yên"], "answer": 3, "explain": "「家賃は８万円ぐらいまでならいい」 — mẫu ～なら Bài 35 được dùng tự nhiên."}]}, "2": {"title": "Bài 27 — Đọc hiểu Minna no Nihongo", "passage": "ミラーさんは 日本語（にほんご）だけでなく、韓国語（かんこくご）も 話（はな）せます。漢字（かんじ）は ５００字（じ）ぐらい 読（よ）めます。でも、速（はや）く 読（よ）むことは まだ できません。", "questions": [{"q": "Anh Miller nói được những ngôn ngữ nào?", "options": ["Tiếng Nhật và tiếng Hàn", "Chỉ tiếng Nhật", "Tiếng Nhật và tiếng Anh", "Tiếng Hàn và tiếng Trung"], "answer": 0, "explain": "「日本語だけでなく、韓国語も話せます」 — thể khả năng Bài 27."}, {"q": "Anh ấy đọc được khoảng bao nhiêu chữ Hán?", "options": ["Khoảng 100 chữ", "Khoảng 500 chữ", "Khoảng 200 chữ", "Khoảng 1000 chữ"], "answer": 1, "explain": "「漢字は５００字ぐらい読めます」."}, {"q": "Việc gì anh ấy chưa làm được?", "options": ["Đọc nhanh", "Nói tiếng Hàn", "Nghe tiếng Nhật", "Viết chữ Hán"], "answer": 0, "explain": "「速く読むことはまだできません」."}, {"q": "Mẫu ngữ pháp chính của đoạn là gì?", "options": ["Thể bị động", "Thể sai khiến", "Kính ngữ", "Thể khả năng （可能形）"], "answer": 3, "explain": "話せます・読めます・できません đều là thể khả năng — trọng tâm Bài 27."}]}, "3": {"title": "Bài 28 — Đọc hiểu Minna no Nihongo", "passage": "姉（あね）は 音楽（おんがく）を 聞（き）きながら 料理（りょうり）を します。それに、掃除（そうじ）を しながら 電話（でんわ）で 話（はな）すことも あります。姉（あね）は 何（なに）かを しながら、別（べつ）の ことも できる 人（ひと）です。", "questions": [{"q": "Chị gái làm gì trong khi nghe nhạc?", "options": ["Học bài", "Nấu ăn", "Chạy bộ", "Dọn dẹp"], "answer": 1, "explain": "「音楽を聞きながら料理をします」 — mẫu ～ながら Bài 28."}, {"q": "Chị còn làm hai việc cùng lúc nào nữa?", "options": ["Ngủ trong khi ăn", "Hát trong khi tắm", "Dọn dẹp trong khi nói điện thoại", "Đọc sách trong khi lái xe"], "answer": 2, "explain": "「掃除をしながら電話で話すこともあります」."}, {"q": "Chị gái là người như thế nào?", "options": ["Rất chậm chạp", "Có thể làm việc khác trong khi làm một việc", "Không thích âm nhạc", "Chỉ làm được một việc một lúc"], "answer": 1, "explain": "Câu cuối tóm tắt: 「何かをしながら、別のこともできる人です」."}, {"q": "Trạng từ bổ sung 「それに」 ở đầu câu 2 có nghĩa là gì?", "options": ["Hơn nữa / thêm vào đó", "Vì vậy", "Sau đó", "Tuy nhiên"], "answer": 0, "explain": "「それに」 = hơn nữa — liên từ bổ sung của Bài 28."}]}, "4": {"title": "Bài 29 — Đọc hiểu Minna no Nihongo", "passage": "部屋（へや）に 入（はい）ると、窓（まど）が 開（あ）いて いました。電気（でんき）も ついて いました。弟（おとうと）が コップを 割（わ）って しまって、床（ゆか）が 濡（ぬ）れて いました。", "questions": [{"q": "Khi vào phòng, cửa sổ thế nào?", "options": ["Đang đóng", "Không có", "Bị vỡ", "Đang mở"], "answer": 3, "explain": "「窓が開いていました」 — tự động từ あく chỉ trạng thái (Bài 29)."}, {"q": "Đèn điện thế nào?", "options": ["Chưa lắp", "Đang tắt", "Bị hỏng", "Đang bật"], "answer": 3, "explain": "「電気もついていました」 = đèn cũng đang sáng (つく)."}, {"q": "Em trai đã làm gì?", "options": ["Làm đổ nước vào sách", "Làm rơi ví", "Làm vỡ cốc", "Làm bẩn phòng"], "answer": 2, "explain": "「弟がコップを割ってしまって」 — ～てしまう chỉ việc đáng tiếc."}, {"q": "Sàn nhà thế nào?", "options": ["Bị bẩn đất", "Bị ướt", "Bị nứt", "Khô ráo"], "answer": 1, "explain": "「床が濡れていました」 = sàn bị ướt (vì cốc vỡ)."}]}, "5": {"title": "Bài 30 — Đọc hiểu Minna no Nihongo", "passage": "明日（あした）は 友達（ともだち）が 家（いえ）に 来（き）ます。ですから、部屋（へや）を 掃除（そうじ）して おきました。壁（かべ）には 写真（しゃしん）が 貼（は）って あります。冷蔵庫（れいぞうこ）には 飲（の）み物（もの）も 入（い）れて あります。", "questions": [{"q": "Vì sao người viết dọn phòng trước?", "options": ["Ngày mai bạn đến nhà", "Phòng quá bẩn", "Hôm nay có kiểm tra", "Sắp chuyển nhà"], "answer": 0, "explain": "Bạn đến mai nên chuẩn bị trước — mẫu Vて おきます Bài 30."}, {"q": "Trên tường có gì?", "options": ["Bản đồ", "Tranh được treo", "Ảnh được dán sẵn", "Lịch được dán"], "answer": 2, "explain": "「壁には写真が貼ってあります」 — Vて あります chỉ trạng thái đã được sắp đặt."}, {"q": "Trong tủ lạnh có gì?", "options": ["Đồ uống đã để sẵn", "Hoa quả", "Kem", "Thức ăn đã nấu"], "answer": 0, "explain": "「飲み物も入れてあります」 = đồ uống cũng đã để sẵn trong tủ lạnh."}, {"q": "Người viết đã làm việc chuẩn bị nào?", "options": ["Đặt nhà hàng", "Dọn phòng, dán ảnh, để đồ uống vào tủ lạnh", "Sơn tường, mua bàn ghế", "Nấu ăn, mua quà, giặt đồ"], "answer": 1, "explain": "Cả ba hành động ～ておく/～てある trong đoạn đều là chuẩn bị cho bạn đến."}]}, "6": {"title": "Bài 31 — Đọc hiểu Minna no Nihongo", "passage": "私（わたし）は 来年（らいねん）、国（くに）へ 帰（かえ）ろうと 思（おも）っています。帰（かえ）ったら、家族（かぞく）と いっしょに 小（ちい）さな 店（みせ）を 開（ひら）く つもりです。まだ 両親（りょうしん）には 話（はな）して いません。", "questions": [{"q": "Người viết định làm gì năm sau?", "options": ["Đổi việc", "Đi du học", "Về nước", "Ở lại Nhật làm việc"], "answer": 2, "explain": "「来年、国へ帰ろうと思っています」 — thể ý chí + と思っています (Bài 31)."}, {"q": "Sau khi về nước, người viết dự định làm gì?", "options": ["Học tiếp đại học", "Đi du lịch", "Làm việc cho công ty Nhật", "Mở cửa hàng nhỏ cùng gia đình"], "answer": 3, "explain": "「家族といっしょに小さな店を開くつもりです」 — ～つもりです chỉ dự định chắc chắn."}, {"q": "Người viết đã nói với bố mẹ chưa?", "options": ["Đã nói rồi", "Sẽ nói tuần sau", "Chỉ nói với mẹ", "Chưa nói"], "answer": 3, "explain": "「まだ両親には話していません」 — まだ～ていません = vẫn chưa làm."}, {"q": "Mẫu ～ようと思っています khác ～つもりです thế nào trong đoạn?", "options": ["～つもりです chỉ dùng cho quá khứ", "～ようと思っています chỉ dùng cho người khác", "～ようと思っています là ý định đang cân nhắc; ～つもりです là dự định đã quyết", "Hai mẫu hoàn toàn giống nhau"], "answer": 2, "explain": "Bài 31 phân biệt: ý chí + と思っています (đang nghĩ, sẽ làm) với つもりです (dự định chắc chắn)."}]}, "7": {"title": "Bài 32 — Đọc hiểu Minna no Nihongo", "passage": "天気予報（てんきよほう）に よると、明日（あした）は 雨（あめ）が 降（ふ）るでしょう。傘（かさ）を 持（も）って 行（い）ったほうが いいです。風邪（かぜ）を ひいて いる 人（ひと）は、無理（むり）を しないほうが いいでしょう。", "questions": [{"q": "Ngày mai thời tiết thế nào theo dự báo?", "options": ["Chắc sẽ nắng", "Không rõ", "Có thể có tuyết", "Chắc sẽ mưa"], "answer": 3, "explain": "「雨が降るでしょう」 — dự đoán xác suất cao Bài 32."}, {"q": "Người viết khuyên mang theo gì?", "options": ["Mũ", "Khăn", "Ô", "Áo mưa"], "answer": 2, "explain": "「傘を持って行ったほうがいいです」 — lời khuyên ～たほうがいい."}, {"q": "Người bị cảm được khuyên thế nào?", "options": ["Không nên cố quá sức", "Nên tập thể thao mạnh", "Nên uống nhiều cà phê", "Nên đi ra ngoài"], "answer": 0, "explain": "「無理をしないほうがいいでしょう」 = không nên gắng sức (～ないほうがいい)."}, {"q": "～でしょう trong đoạn diễn tả điều gì?", "options": ["Sự thật đã xác nhận 100%", "Câu hỏi về quá khứ", "Mệnh lệnh tuyệt đối", "Suy đoán / khuyên nhẹ nhàng"], "answer": 3, "explain": "Bài 32: ～でしょう dùng cho dự đoán và lời khuyên có căn cứ nhưng chưa chắc chắn tuyệt đối."}]}, "8": {"title": "Bài 33 — Đọc hiểu Minna no Nihongo", "passage": "駅（えき）の ドアに「押（お）すな」と 書（か）いて あります。先生（せんせい）は「静（しず）かに しなさい」と 言（い）いました。この 学校（がっこう）では「走（はし）るな」という 標識（ひょうしき）も あります。", "questions": [{"q": "Trên cửa ở ga viết gì?", "options": ["「押すな」 (Cấm đẩy)", "「引け」 (Hãy kéo)", "「開けるな」", "「押せ」 (Hãy đẩy)"], "answer": 0, "explain": "「押すなと書いてあります」 — thể cấm đoán Bài 33."}, {"q": "Thầy/cô đã bảo học sinh điều gì?", "options": ["Hãy ra ngoài", "Hãy đọc to", "Hãy yên lặng", "Hãy ngồi xuống"], "answer": 2, "explain": "「静かにしなさいと言いました」 — mệnh lệnh ～なさい được truyền đạt lại."}, {"q": "「走るな」 có nghĩa là gì?", "options": ["Không chạy được", "Cấm chạy", "Hãy chạy", "Chạy chậm lại"], "answer": 1, "explain": "～な sau thể từ điển là cấm đoán: 走るな = cấm chạy."}, {"q": "Mẫu ～と書いてあります diễn tả điều gì?", "options": ["Ai đó đang viết", "Đã viết xong thư", "Phải viết ngay", "Chữ/nội dung được viết sẵn ở đâu đó"], "answer": 3, "explain": "Bài 33: ～と書いてあります = có viết rằng... (trạng thái chữ viết hiện hữu)."}]}, "9": {"title": "Bài 34 — Đọc hiểu Minna no Nihongo", "passage": "先生（せんせい）の 言（い）った とおりに レポートを 書（か）きました。宿題（しゅくだい）を した 後（あと）で、友達（ともだち）と 会（あ）いました。友達（ともだち）は 眼鏡（めがね）を かけないで 本（ほん）を 読（よ）んで いました。", "questions": [{"q": "Người viết viết báo cáo như thế nào?", "options": ["Theo sách mẫu", "Theo ý mình", "Sao chép của bạn", "Đúng như thầy đã nói"], "answer": 3, "explain": "「先生の言ったとおりに」 — Vた + とおりに Bài 34."}, {"q": "Sau khi làm bài tập, người viết làm gì?", "options": ["Xem tivi", "Đi ngủ", "Đi mua sắm", "Gặp bạn"], "answer": 3, "explain": "「宿題をした後で、友達と会いました」 — Vた後で."}, {"q": "Bạn của người viết đọc sách như thế nào?", "options": ["Không đeo kính", "Đọc to", "Đeo kính", "Nằm đọc"], "answer": 0, "explain": "「眼鏡をかけないで本を読んでいました」 — Vないで = mà không (đeo kính)."}, {"q": "Ba mẫu chính của Bài 34 xuất hiện trong đoạn là gì?", "options": ["～ても / ～たら / ～ば", "～とおりに / ～た後で / ～ないで", "～そうだ / ～ようだ / ～らしい", "～ながら / ～つつ / ～ばかり"], "answer": 1, "explain": "Cả ba mẫu Bài 34 đều xuất hiện lần lượt trong ba câu của đoạn."}]}, "10": {"title": "Bài 35 — Đọc hiểu Minna no Nihongo", "passage": "安（やす）ければ 買（か）いますが、高（たか）ければ 買（か）いません。時間（じかん）が あれば、旅行（りょこう）に 行（い）きたいです。何（なに）か あれば、いつでも 相談（そうだん）して ください。", "questions": [{"q": "Người viết sẽ mua khi nào?", "options": ["Khi có giảm giá 50%", "Khi đắt", "Khi rẻ", "Khi có lương"], "answer": 2, "explain": "「安ければ買います」 — thể điều kiện ば Bài 35."}, {"q": "Nếu có thời gian, người viết muốn làm gì?", "options": ["Đi làm thêm", "Học nấu ăn", "Ngủ cả ngày", "Đi du lịch"], "answer": 3, "explain": "「時間があれば、旅行に行きたいです」."}, {"q": "Khi có chuyện gì, người nghe nên làm gì?", "options": ["Cứ相談 (trao đổi) bất cứ lúc nào", "Chờ đến tuần sau", "Gọi điện vào ban đêm", "Viết thư"], "answer": 0, "explain": "「何かあれば、いつでも相談してください」 — 疑問詞 + でも trong câu cuối."}, {"q": "Thể ば của 「安い」 và 「ある」 trong đoạn là gì?", "options": ["安かったら / あったら", "安くば / あらば", "安いば / あるば", "安ければ / あれば"], "answer": 3, "explain": "Tính từ い: 安い→安ければ; động từ ある→あれば. Đây là cách chia thể ば Bài 35."}]}, "11": {"title": "Bài 36 — Đọc hiểu Minna no Nihongo", "passage": "日本語（にほんご）が 上手（じょうず）に 話（はな）せるように、毎日（まいにち）練習（れんしゅう）して います。最近（さいきん）、ニュースも 聞（き）き取（と）れるように なりました。忘（わす）れないように、単語（たんご）は ノートに 書（か）くように して います。", "questions": [{"q": "Người viết luyện tập mỗi ngày để làm gì?", "options": ["Để làm phiên dịch", "Để nói tiếng Nhật giỏi được", "Để dạy tiếng Nhật", "Để thi đỗ N1 ngay"], "answer": 1, "explain": "「話せるように、毎日練習しています」 — mục đích ～ように Bài 36."}, {"q": "Gần đây người viết đã đạt được thay đổi gì?", "options": ["Dạy được trẻ em", "Viết được thư dài", "Nghe hiểu được tin tức", "Đọc được báo"], "answer": 2, "explain": "「ニュースも聞き取れるようになりました」 — ～ようになりました chỉ thay đổi trạng thái."}, {"q": "Để không quên từ, người viết cố gắng làm gì?", "options": ["Học thuộc lòng 100 từ/ngày", "Dán giấy khắp phòng", "Đọc to mỗi sáng", "Viết từ vào vở"], "answer": 3, "explain": "「単語はノートに書くようにしています」 — ～ようにしています = cố gắng duy trì thói quen."}, {"q": "Ba cách dùng ～ように trong đoạn tương ứng là gì?", "options": ["Quá khứ / hiện tại / tương lai", "Mục đích / thay đổi trạng thái / cố gắng duy trì thói quen", "Dự đoán / nghe nói / so sánh", "Mệnh lệnh / cấm đoán / xin phép"], "answer": 1, "explain": "Đoạn văn dùng đủ ba mẫu Bài 36: ～ように (mục đích), ～ようになる (thay đổi), ～ようにする (cố gắng)."}]}, "12": {"title": "Bài 37 — Đọc hiểu Minna no Nihongo", "passage": "私（わたし）は 先生（せんせい）に 褒（ほ）められました。でも、昨日（きのう）は 雨（あめ）に 降（ふ）られて、靴（くつ）が 濡（ぬ）れて しまいました。この 学校（がっこう）は ５０年（ねん）前（まえ）に 建（た）てられました。", "questions": [{"q": "Người viết được thầy làm gì?", "options": ["Khen", "Mời ăn", "Giao bài tập", "Mắng"], "answer": 0, "explain": "「先生に褒められました」 — bị động trực tiếp Bài 37."}, {"q": "Hôm qua người viết gặp chuyện gì không may?", "options": ["Bị mưa làm ướt giày", "Bị mất ví", "Bị trễ tàu", "Bị ngã"], "answer": 0, "explain": "「雨に降られて、靴が濡れてしまいました」 — bị động bất lợi kinh điển."}, {"q": "Ngôi trường được xây khi nào?", "options": ["Năm ngoái", "50 năm trước", "100 năm trước", "10 năm trước"], "answer": 1, "explain": "「５０年前に建てられました」 = được xây 50 năm trước."}, {"q": "Trợ từ chỉ tác nhân trong câu bị động của đoạn là gì?", "options": ["に", "を", "へ", "と"], "answer": 0, "explain": "Cả 先生に・雨に đều dùng 「に」 cho tác nhân/nguyên nhân bị động."}]}, "13": {"title": "Bài 38 — Đọc hiểu Minna no Nihongo", "passage": "自転車（じてんしゃ）に 乗（の）るのは 楽（たの）しいです。でも、鍵（かぎ）を かけるのを 忘（わす）れることが あります。彼（かれ）が 来（き）たのを 知（し）って いましたか。", "questions": [{"q": "Việc gì được nói là vui?", "options": ["Đi xe đạp", "Sửa xe đạp", "Mua xe đạp", "Khóa xe đạp"], "answer": 0, "explain": "「自転車に乗るのは楽しいです」 — danh từ hóa bằng の Bài 38."}, {"q": "Người viết thỉnh thoảng quên làm gì?", "options": ["Khóa (xe)", "Bơm xe", "Để xe đúng chỗ", "Đội mũ bảo hiểm"], "answer": 0, "explain": "「鍵をかけるのを忘れることがあります」 — Vる + のを忘れる."}, {"q": "Câu cuối hỏi về điều gì?", "options": ["Việc anh ấy đi xe", "Việc anh ấy đã đến", "Việc anh ấy sẽ đến", "Việc anh ấy quên khóa"], "answer": 1, "explain": "「彼が来たのを知っていましたか」 = Bạn có biết việc anh ấy đã đến không?"}, {"q": "Mẫu ～の trong Bài 38 có chức năng gì?", "options": ["Biến mệnh đề thành cụm danh từ", "Chỉ điều kiện", "Chỉ nguyên nhân", "Chỉ thời gian"], "answer": 0, "explain": "～の danh từ hóa: 乗るの・かけるの・来たの đều biến hành động thành 'việc...' để làm chủ ngữ/tân ngữ."}]}, "14": {"title": "Bài 39 — Đọc hiểu Minna no Nihongo", "passage": "電車（でんしゃ）が 遅（おく）れて、会議（かいぎ）に 間（ま）に合いませんでした。頭（あたま）が 痛（いた）くて、午後（ごご）は 休（やす）みました。その ニュースを 聞（き）いて、みんな 驚（おどろ）きました。", "questions": [{"q": "Vì sao người viết không kịp họp?", "options": ["Ngủ quên", "Họp đổi giờ", "Tàu đến muộn", "Lạc đường"], "answer": 2, "explain": "「電車が遅れて」 — lý do bằng thể て Bài 39."}, {"q": "Vì sao người viết nghỉ buổi chiều?", "options": ["Đau bụng", "Đi khám bệnh", "Bị cảm nặng", "Đau đầu"], "answer": 3, "explain": "「頭が痛くて、午後は休みました」 — tính từ い thể て chỉ lý do."}, {"q": "Mọi người ngạc nhiên vì điều gì?", "options": ["Thấy tuyết rơi", "Gặp người nổi tiếng", "Nghe tin tức đó", "Nghe tiếng động lớn"], "answer": 2, "explain": "「そのニュースを聞いて、みんな驚きました」."}, {"q": "Điểm chung của ba mẫu lý do trong đoạn là gì?", "options": ["Đều dùng ので", "Đều dùng から", "Đều dùng ため", "Đều dùng thể て (Vて / Adjくて) để nối nguyên nhân"], "answer": 3, "explain": "Bài 39: lý do nối bằng thể て — 遅れて・痛くて・聞いて."}]}, "15": {"title": "Bài 40 — Đọc hiểu Minna no Nihongo", "passage": "彼（かれ）が 何時（なんじ）に 来（く）るか、知（し）りません。一度（いちど）この 料理（りょうり）を 食（た）べて みます。この 薬（くすり）は １日（にち）に 何回（なんかい）飲（の）めば いいか、教（おし）えて ください。", "questions": [{"q": "Người viết không biết điều gì?", "options": ["Anh ấy làm nghề gì", "Anh ấy đi đâu", "Anh ấy ăn gì", "Anh ấy đến lúc mấy giờ"], "answer": 3, "explain": "「彼が何時に来るか、知りません」 — câu hỏi lồng ～か Bài 40."}, {"q": "Người viết định thử làm gì?", "options": ["Nấu thử món này", "Ăn thử món ăn này một lần", "Mua thử thuốc", "Đi thử nơi này"], "answer": 1, "explain": "「一度この料理を食べてみます」 — Vて みます = thử làm."}, {"q": "Câu cuối nhờ chỉ điều gì?", "options": ["Thuốc này giá bao nhiêu", "Thuốc này có đắng không", "Thuốc này mua ở đâu", "Thuốc này uống mấy lần một ngày"], "answer": 3, "explain": "「１日に何回飲めばいいか、教えてください」 — từ nghi vấn 何回 + か."}, {"q": "Mẫu ～か trong đoạn thuộc loại câu nào?", "options": ["Câu hỏi trực tiếp cuối câu", "Câu hỏi gián tiếp/lồng trong câu lớn", "Câu mệnh lệnh", "Câu cảm thán"], "answer": 1, "explain": "Bài 40: câu hỏi con được lồng vào câu chính bằng ～か (biết/không biết/hãy cho biết)."}]}, "16": {"title": "Bài 41 — Đọc hiểu Minna no Nihongo", "passage": "部長（ぶちょう）に レポートを 見（み）て いただきました。駅（えき）では、知（し）らない 人（ひと）が 荷物（にもつ）を 持（も）って くださいました。私（わたし）は 子供（こども）に 本（ほん）を 読（よ）んで やりました。", "questions": [{"q": "Người viết được trưởng phòng làm gì cho?", "options": ["Xem báo cáo cho", "Mời đi ăn", "Khen", "Cho nghỉ phép"], "answer": 0, "explain": "「部長にレポートを見ていただきました」 — kính ngữ nhận ân huệ Bài 41."}, {"q": "Ở ga, người lạ đã làm gì?", "options": ["Mua vé giúp", "Cho mượn ô", "Chỉ đường", "Xách hành lý giúp"], "answer": 3, "explain": "「荷物を持ってくださいました」 = đã cầm hành lý cho (tôi)."}, {"q": "Người viết đọc sách cho ai?", "options": ["Cho người lạ", "Cho học sinh", "Cho con/trẻ em", "Cho trưởng phòng"], "answer": 2, "explain": "「子供に本を読んでやりました」 — Vて やります cho người dưới."}, {"q": "Ba động từ ân huệ trong đoạn xếp theo quan hệ nào?", "options": ["Tất cả đều là người khác cho mình", "いただく (từ người trên) / くださる (người khác cho mình) / やる (mình cho người dưới)", "Tất cả đều là mình cho người khác", "Không liên quan đến quan hệ trên dưới"], "answer": 1, "explain": "Bài 41 phân tầng ân huệ theo quan hệ: いただきました・くださいました・やりました."}]}, "17": {"title": "Bài 42 — Đọc hiểu Minna no Nihongo", "passage": "試験（しけん）に 合格（ごうかく）する ために、毎日（まいにち）勉強（べんきょう）して います。この 部屋（へや）は ３０人（にん）は 入（はい）れます。レポートを 終（お）わるまでに ３日（か）も かかりました。", "questions": [{"q": "Người viết học mỗi ngày để làm gì?", "options": ["Để đỗ kỳ thi", "Để đi du học", "Để xin việc", "Để làm giáo viên"], "answer": 0, "explain": "「合格するために」 — mục đích ～ために Bài 42."}, {"q": "Phòng này chứa được ít nhất bao nhiêu người?", "options": ["Khoảng 13 người", "Ít nhất 30 người", "Đúng 30 người", "Nhiều nhất 30 người"], "answer": 1, "explain": "「３０人は入れます」 — số lượng + は = ít nhất."}, {"q": "Viết báo cáo mất bao lâu?", "options": ["Tới 3 ngày", "Khoảng 3 giờ", "Hơn 1 tuần", "Chỉ 1 ngày"], "answer": 0, "explain": "「３日もかかりました」 — số lượng + も = tới/đến (nhiều hơn tưởng)."}, {"q": "～は và ～も sau số lượng trong đoạn khác nhau thế nào?", "options": ["Cả hai đều nghĩa 'khoảng'", "は = nhiều tới mức; も = ít nhất", "は = ít nhất; も = nhiều tới mức", "Cả hai đều nghĩa 'đúng bằng'"], "answer": 2, "explain": "Bài 42: ～は nhấn mạnh mức tối thiểu, ～も nhấn mạnh mức lớn đáng ngạc nhiên."}]}, "18": {"title": "Bài 43 — Đọc hiểu Minna no Nihongo", "passage": "彼女（かのじょ）は 眠（ねむ）そうな 顔（かお）を して います。この ケーキは おいしそうです。雨（あめ）が 降（ふ）って きました。帰（かえ）りましょう。", "questions": [{"q": "Cô ấy có vẻ mặt thế nào?", "options": ["Trông vui vẻ", "Trông tức giận", "Trông ngạc nhiên", "Trông buồn ngủ"], "answer": 3, "explain": "「眠そうな顔」 —様態 ～そうです Bài 43 (trông có vẻ)."}, {"q": "Bánh kem trông thế nào?", "options": ["Trông cũ", "Trông ngon", "Trông nhỏ", "Trông đắt"], "answer": 1, "explain": "「おいしそうです」 = trông ngon (đánh giá từ vẻ ngoài)."}, {"q": "Thời tiết thay đổi ra sao?", "options": ["Mưa bắt đầu rơi", "Gió mạnh lên", "Mưa tạnh", "Tuyết rơi"], "answer": 0, "explain": "「雨が降ってきました」 — ～てきました chỉ sự bắt đầu/hướng về hiện tại."}, {"q": "～そうです trong đoạn này khác ～そうです truyền văn （Bài 47) ở điểm nào?", "options": ["Đây là mệnh lệnh", "Đây là đánh giá từ vẻ bề ngoài, không phải nghe nói lại", "Đây là nghe nói từ người khác", "Đây là dự báo thời tiết"], "answer": 1, "explain": "Bài 43 là様態 （vẻ ngoài）; Bài 47 mới là伝聞 (nghe nói) — hai mẫu dễ nhầm nhất ở N4."}]}, "19": {"title": "Bài 44 — Đọc hiểu Minna no Nihongo", "passage": "昨日（きのう）、コーヒーを 飲（の）みすぎて、眠（ねむ）れませんでした。この 本（ほん）は 読（よ）みやすいです。でも、その 本（ほん）は 字（じ）が 小（ちい）さくて 読（よ）みにくいです。音（おと）を 大（おお）きく して ください。", "questions": [{"q": "Vì sao hôm qua người viết không ngủ được?", "options": ["Uống cà phê quá nhiều", "Đau đầu", "Ồn ào", "Đọc sách khuya"], "answer": 0, "explain": "「コーヒーを飲みすぎて」 — ～すぎます Bài 44."}, {"q": "Quyển sách đầu tiên thế nào?", "options": ["Khó đọc", "Rất dày", "Rất cũ", "Dễ đọc"], "answer": 3, "explain": "「読みやすいです」 — thân Vます + やすい = dễ làm."}, {"q": "Vì sao quyển sách thứ hai khó đọc?", "options": ["Giấy mỏng", "Nội dung khó", "Quá dài", "Chữ nhỏ"], "answer": 3, "explain": "「字が小さくて読みにくいです」 — ～にくい = khó làm."}, {"q": "Lời yêu cầu cuối đoạn là gì?", "options": ["Vặn âm lượng to lên", "Tắt nhạc", "Mở cửa sổ", "Vặn âm lượng nhỏ xuống"], "answer": 0, "explain": "「音を大きくしてください」 — tính từ い + くする = làm cho to lên."}]}, "20": {"title": "Bài 45 — Đọc hiểu Minna no Nihongo", "passage": "事故（じこ）が あった 場合（ばあい）は、すぐ 警察（けいさつ）に 連絡（れんらく）して ください。忙（いそが）しいのに、彼（かれ）は 手伝（てつだ）って くれました。この ボタンを 押（お）す 場合（ばあい）は、注意（ちゅうい）が 必要（ひつよう）です。", "questions": [{"q": "Khi có tai nạn phải làm gì ngay?", "options": ["Gọi xe cấp cứu trước", "Về nhà", "Liên lạc với cảnh sát", "Chụp ảnh hiện trường"], "answer": 2, "explain": "「事故があった場合は、すぐ警察に連絡してください」 — ～場合は Bài 45."}, {"q": "Anh ấy đã làm gì dù đang bận?", "options": ["Vẫn giúp đỡ", "Hủy cuộc hẹn", "Nhờ người khác thay", "Đi về sớm"], "answer": 0, "explain": "「忙しいのに、手伝ってくれました」 — ～のに = mặc dù (trái kỳ vọng)."}, {"q": "Khi bấm nút này cần điều gì?", "options": ["Cần hai người", "Cần mật khẩu", "Cần chú ý/cẩn thận", "Cần găng tay"], "answer": 2, "explain": "「押す場合は、注意が必要です」."}, {"q": "～のに và ～場合は khác nhau thế nào?", "options": ["Cả hai đều là 'nếu'", "のに = trong trường hợp; 場合は = mặc dù", "のに = mặc dù (trái kỳ vọng); 場合は = trong trường hợp", "Cả hai đều là 'vì'"], "answer": 2, "explain": "Bài 45 đối chiếu hai mẫu: nhượng bộ trái kỳ vọng （のに） và tình huống giả định trang trọng （場合は）."}]}, "21": {"title": "Bài 46 — Đọc hiểu Minna no Nihongo", "passage": "今（いま）、出（で）かけようとして いる ところです。彼（かれ）は たった今（いま）帰（かえ）った ところです。この 仕事（しごと）は 明日（あした）終（お）わる はずです。彼（かれ）は 寝（ね）て ばかり います。", "questions": [{"q": "Người viết đang ở giai đoạn nào của hành động 'ra ngoài'?", "options": ["Đang ở ngoài", "Vừa mới về", "Đang sắp ra ngoài", "Đã hủy kế hoạch"], "answer": 2, "explain": "「出かけようとしているところです」 — ～ようとするところ = đang sắp làm (Bài 46)."}, {"q": "Anh ấy vừa làm gì xong?", "options": ["Vừa ăn xong", "Vừa mới về", "Vừa ngủ dậy", "Vừa mới đi"], "answer": 1, "explain": "「たった今帰ったところです」 — Vた ところ = vừa mới làm xong."}, {"q": "Công việc được kỳ vọng thế nào?", "options": ["Chắc chắn mai sẽ xong", "Có thể không xong", "Sẽ xong tuần sau", "Đã xong hôm qua"], "answer": 0, "explain": "「明日終わるはずです」 — ～はずです = chắc chắn (theo căn cứ)."}, {"q": "Anh ấy bị chê vì điều gì?", "options": ["Chỉ toàn chơi game", "Chỉ toàn ngủ", "Chỉ toàn ăn", "Chỉ toàn xem tivi"], "answer": 1, "explain": "「寝てばかりいます」 — Vて ばかり = chỉ toàn làm một việc."}]}, "22": {"title": "Bài 47 — Đọc hiểu Minna no Nihongo", "passage": "ニュースに よると、明日（あした）は 雨（あめ）だそうです。彼（かれ）は 病気（びょうき）で 休（やす）んだそうです。あの レストランは 人気（にんき）が あるようです。", "questions": [{"q": "Theo tin tức, ngày mai thế nào?", "options": ["Nghe nói có tuyết", "Chắc chắn nắng", "Không có thông tin", "Nghe nói sẽ mưa"], "answer": 3, "explain": "「明日は雨だそうです」 — ～そうです truyền văn Bài 47 (nguồn: ニュースによると)."}, {"q": "Nghe nói anh ấy nghỉ vì lý do gì?", "options": ["Bị ốm", "Đi du lịch", "Chuyển nhà", "Bận việc nhà"], "answer": 0, "explain": "「病気で休んだそうです」 = nghe nói nghỉ vì ốm."}, {"q": "Nhà hàng kia được đánh giá thế nào?", "options": ["Có vẻ nổi tiếng/được ưa chuộng", "Có vẻ vắng", "Có vẻ cũ", "Có vẻ đắt"], "answer": 0, "explain": "「人気があるようです」 — ～ようです suy đoán từ quan sát."}, {"q": "～そうです và ～ようです trong đoạn khác nhau ra sao?", "options": ["そうです = vẻ ngoài; ようです = nghe nói", "そうです = nghe nói lại; ようです = tự suy đoán từ dấu hiệu", "Cả hai đều là nghe nói", "Cả hai đều là vẻ bề ngoài"], "answer": 1, "explain": "Bài 47 phân biệt伝聞 （そうです） với推 lượng từ căn cứ quan sát （ようです/らしいです）."}]}, "23": {"title": "Bài 48 — Đọc hiểu Minna no Nihongo", "passage": "社長（しゃちょう）は 私（わたし）に レポートを 書（か）かせました。すみません、ここで 写真（しゃしん）を 撮（と）らせて ください。先生（せんせい）は 学生（がくせい）に 本（ほん）を 読（よ）ませました。", "questions": [{"q": "Giám đốc đã bắt người viết làm gì?", "options": ["Đọc sách", "Dọn phòng", "Chụp ảnh", "Viết báo cáo"], "answer": 3, "explain": "「レポートを書かせました」 — thể sai khiến Bài 48."}, {"q": "Câu thứ hai là yêu cầu gì?", "options": ["Cấm chụp ảnh ở đây", "Xin cho tôi chụp ảnh ở đây", "Hãy chụp ảnh đi", "Xin chụp giúp tôi một tấm"], "answer": 1, "explain": "「撮らせてください」 — V使役て + ください = xin hãy cho tôi làm."}, {"q": "Thầy đã bắt học sinh làm gì?", "options": ["Viết báo cáo", "Làm bài tập", "Đọc sách", "Dọn lớp"], "answer": 2, "explain": "「学生に本を読ませました」 = bắt học sinh đọc sách."}, {"q": "Trong câu sai khiến, người bị bắt làm việc được đánh dấu bằng trợ từ nào trong đoạn?", "options": ["を", "に", "へ", "が"], "answer": 1, "explain": "私に・学生に — người thực hiện hành động bị sai khiến dùng 「に」 (khi động từ có tân ngữ を)."}]}, "24": {"title": "Bài 49 — Đọc hiểu Minna no Nihongo", "passage": "社長（しゃちょう）は もう お帰（かえ）りに なりました。先生（せんせい）は この 本（ほん）を お読（よ）みに なりました。お客様（きゃくさま）は あちらに いらっしゃいます。", "questions": [{"q": "Giám đốc đã làm gì?", "options": ["Đã về rồi", "Đã đến rồi", "Đang họp", "Đã ăn trưa"], "answer": 0, "explain": "「お帰りになりました」 — kính ngữ お～になる Bài 49."}, {"q": "Thầy/cô đã làm gì với quyển sách?", "options": ["Đã đọc", "Đã viết", "Đã mua", "Đã cho mượn"], "answer": 0, "explain": "「この本をお読みになりました」 = thầy đã đọc quyển sách này."}, {"q": "Khách đang ở đâu?", "options": ["Ở đằng kia", "Ở ngoài cửa", "Đã ra về", "Ở phòng họp"], "answer": 0, "explain": "「お客様はあちらにいらっしゃいます」 — いらっしゃいます là kính ngữ đặc biệt của います."}, {"q": "Cả ba câu trong đoạn đều dùng loại kính ngữ nào?", "options": ["謙譲語 (hạ mình xuống)", "尊敬語 (nâng người trên lên)", "Thể thường thân mật", "丁寧語 thông thường"], "answer": 1, "explain": "Bài 49 là尊敬語： お～になる và động từ kính ngữ đặc biệt （いらっしゃる）."}]}, "25": {"title": "Bài 50 — Đọc hiểu Minna no Nihongo", "passage": "私（わたし）が ご案内（あんない）いたします。明日（あした）３時（じ）に うかがいます。私（わたし）は 田中（たなか）と 申（もう）します。部長（ぶちょう）に プレゼントを さしあげました。", "questions": [{"q": "Người viết sẽ làm gì cho khách?", "options": ["Hướng dẫn (khiêm nhường)", "Bán hàng", "Mời ăn", "Đưa đi sân bay"], "answer": 0, "explain": "「私がご案内いたします」 — khiêm nhường ngữ ご～いたします Bài 50."}, {"q": "Ngày mai lúc 3 giờ người viết làm gì?", "options": ["Đón khách ở ga", "Đi họp ở công ty mình", "Đến thăm/đến gặp (nơi của người trên)", "Về quê"], "answer": 2, "explain": "「３時にうかがいます」 — うかがう là khiêm nhường ngữ của 行く/聞く (đến thăm)."}, {"q": "Người viết tự giới thiệu tên bằng mẫu nào?", "options": ["～とご覧になります", "～でいらっしゃいます", "～と申します", "～とおっしゃいます"], "answer": 2, "explain": "「田中と申します」 — 申す là khiêm nhường của 言う khi nói về mình."}, {"q": "Người viết đã tặng quà cho ai?", "options": ["Trưởng phòng", "Bạn", "Thầy giáo", "Khách hàng"], "answer": 0, "explain": "「部長にプレゼントをさしあげました」 — さしあげる là khiêm nhường của あげる (tặng người trên)."}]}}};
